    description: description,
    icon: icon,
    declaredPermissions: declaredPermissions,
    nameText: nameText,
    descriptionText: descriptionText,
    version: version,
    chrome: chrome,
    tileWidget: tileWidget,
    bundled: bundled,
    platforms: platforms,
    dirOverride: dirOverride,
    error: error ?? message,
  );

