  ///
  /// Manifest identifiers are `web`, `android`, `ios`, `macos`, `windows`,
  /// `linux`, and `fuchsia`.
  final Set<String>? platforms;

  bool supportsPlatform(String platform) =>
      platforms == null || platforms!.contains(platform.toLowerCase());

