      }
      final content = (await _env.readTextFile('${app.dir}/$path')).valueOrNull;
      if (content != null) {
        contents[path] = content;
        digests[path] = _digest(content);
      } else {
        AppLog.i('apps', 'i18n ref ${app.dir}/$path missing — skipped');
      }
    }
