      icon: (json['icon'] ?? '📦').toString(),
      version: (json['version'] ?? '1.0.0').toString(),
      chrome: json['chrome'] == chromeFull ? chromeFull : chromeHeader,
      tileWidget: widget is Map<String, Object?>
