    this.version = '1.0.0',
    this.chrome = chromeHeader,
    this.tileWidget,
    this.bundled = false,
    this.platforms,
    this.dirOverride,
    this.error,
  });

  factory JsAppInfo.fromManifest(
    Map<String, Object?> json, {
    required bool bundled,
    required String fallbackId,
  }) {
    final widget = json['widget'];
