    // listed copy only, so a later scan (entry restored) heals the tile
    // without a re-parse.
    _manifestHashes[id] = hash;
    _parsedApps[id] = app;
    final listed = missingEntry == null ? app : app.withError(missingEntry);
    if (listed.supportsPlatform(platform)) apps.add(listed);
