/// defaults to denied; the user can grant/deny per app at runtime (see
/// [AppPermissionsStore]).
class AppPermissions {
  const AppPermissions({
    this.network = false,
    this.allowedCommands = const [],
    this.llm = false,
    this.homekit = false,
