      // user-owned now and is left alone.
      await env.writeFile(
        'apps/demo/manifest.json',
        _manifest.replaceAll('Demo App', 'Edited App'),
      );
      await store.seedBundledApps(['demo']);
      apps = await store.listApps();
      expect(apps.single.name, 'Edited App');

