/// Probes every launch surface's boot entry (gh-1614 I2): the full-app
/// entry ([AppStorage.entryPath]) and — when the manifest declares a
/// live-tile widget — the tile entry ([JsAppInfo.tileWidgetPath], the
/// path AppTileHost boots). Returns null when every surface resolves;
/// otherwise the missing-files message naming the first missing path.
Future<String?> _missingBootEntry(String id, {String? tileEntry}) async {
  if (!((await _env.exists(AppStorage.entryPath(id))).valueOrNull ?? false)) {
    return _missingEntryMessage(id);
  }
  if (tileEntry != null &&
      !((await _env.exists(AppStorage.entryPath(id, tileEntry))).valueOrNull ??
          false)) {
    return _missingEntryMessage(id, entry: tileEntry);
  }
  return null;
}
