/// `apps/<id>/…` path for listing AND reading — the table pins the exact
/// shapes (VM and web compile the same pure Dart, so the resolution is
/// host-independent by construction; the parity requirement is that no
/// branch anywhere consults the host platform).
void main() {
  group('AppStorage id validation (gh-1614 AC4)', () {
    const valid = [
      '2048',
      'ab',
      'my-app',
      'a0',
      '0-0',
      'english-teacher',
      'axxxxxxxxxxxxxxxxxxxxxxxxxxxxxxb', // 32 chars — the upper bound
    ];
    for (final id in valid) {
      test('accepts "$id"', () => expect(AppStorage.isValidId(id), isTrue));
    }
    const invalid = [
      '', // empty
      '..', // traversal
      '../x', // traversal
      'a/../b', // embedded traversal
      'a/..', // trailing traversal
      '/absolute', // absolute
      'apps/../evil', // namespace escape through the root
      'a_b', // underscore
      'My-App', // uppercase
      'приложение', // unicode
      'a b', // space
      'a.b', // dot
      '.hidden', // dot-file
      '-abc', // leading dash
      'a/b', // separator
      'a\\b', // windows separator
      'axxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxb', // 33 chars — over the bound
    ];
    for (final id in invalid) {
      test('rejects "$id"', () => expect(AppStorage.isValidId(id), isFalse));
    }

    test('the escape floor resolves legacy ids the strict pattern rejects', () {
      // Existing user stores hold dirs the canonical pattern does not
      // allow; the listing must not hide a user's app over its name.
      expect(AppStorage.isResolvableId('bad_types'), isTrue);
      expect(AppStorage.isResolvableId('a'), isTrue);
      expect(AppStorage.appDir('bad_types'), 'apps/bad_types');
    });

    test('the escape floor still rejects every AC4 shape', () {
      for (final hostile in [
        '',
        '..',
        '../x',
        'a/../b',
        '/abs',
        'apps/../evil',
        'a/b',
        'a\\b',
        '.hidden',
        '.',
      ]) {
        expect(
          AppStorage.isResolvableId(hostile),
          isFalse,
          reason: 'isResolvableId("$hostile") must be false',
        );
        expect(
          () => AppStorage.appDir(hostile),
          throwsA(isA<ArgumentError>()),
          reason: 'appDir("$hostile") must be rejected',
        );
      }
    });

