          name: manifest.name,
          description: manifest.description,
          version: manifest.version,
          icon: manifest.icon,
          allowedCommands: manifest.allowedCommands,
          networkEnabled: manifest.networkEnabled,
          widgetPath: manifest.widgetPath,
          isSingleFile: manifest.isSingleFile,
          cli: manifest.cli,
