@visibleForTesting
static Future<String> computeSourceRevision(
  ExecutionEnv env,
  String dir,
  String entryFile,
) async {
  final files = <(String, String)>[];
  Future<void> walk(String path) async {
    final entries = (await env.listDir(path)).valueOrNull;
    if (entries == null) return;
