Future<String> _fakeAssets(String path) async {
  if (path.endsWith('manifest.json')) return _manifest;
  return '(function(){ jsr.render({type:"text",data:"hi"}); })();';
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

