          id: 'focus-timer',
          version: '1.0.0',
          files: {
            'manifest.json': utf8.encode(
              '{"id":"focus-timer","version":"1.0.0"}',
            ),
            'widget.js': utf8.encode('// ft'),
          },
        );
        await env.writeFile('apps/focus-timer/storage.json', '{"sessions":9}');
        await env.writeFile('apps/my-own/manifest.json', '{"id":"my-own"}');
