  static String _missingEntryMessage(
    String id, {
    String entry = AppStorage.defaultEntry,
  }) =>
      'stored files missing under ${AppStorage.root}/$id/ — the app '
      'cannot start: ${AppStorage.entryPath(id, entry)} is missing or '
