            (e) => e.message,
            'message',
            allOf([
              contains('install of i18n-app rejected'),
              contains('i18n/pt-BR (final).json'),
              contains('not a valid in-namespace path'),
            ]),
          ),
        ),
      );
      expect(await store.isCatalogInstalled('i18n-app'), isFalse);
    });

