  final themeJson = _themeJson;
  final initialTheme = themeJson == null
      ? jsThemeMap(context)
      : jsonDecode(themeJson) as Map<String, dynamic>;
  final old = _engine;
  setState(() {
    _engine = null;
    _startError = null;
  });

