        'write', () async {
      final env = MemoryExecutionEnv();
      final store = AppsStore(env, readAsset: _fakeAssets);
      await expectLater(
        store.installWidget(
          id: 'evil-app',
          version: '1.0.0',
          files: {
            'manifest.json': utf8.encode('{"id":"evil-app"}'),
            '../evil.js': utf8.encode('// namespace escape'),
          },
        ),
