/// The missing-files state for [id]'s every launch surface (gh-1614 I2):
/// the primary boot entry ([AppStorage.entryPath]) and — when the manifest
/// declares a live-tile widget — the tile entry ([JsAppInfo.tileWidgetPath]),
/// which the tile host boots (`AppTileHost` reads exactly that path).
/// Null when every boot entry resolves; otherwise the message names the
/// first missing path.
Future<String?> _missingBootEntry({required String id, String? tileEntry}) async {
  if (!(await _env.exists(AppStorage.entryPath(id))).valueOrNull ?? false) {
    return _missingEntryMessage(id);
  }
  if (tileEntry != null &&
      !((await _env.exists(AppStorage.entryPath(id, tileEntry))).valueOrNull ?? false)) {
    return _missingEntryMessage(id, entry: tileEntry);
  }
  return null;
}
```

