      'valid in-namespace path',
    );
  }
  final onDisk =
      (await _env.exists(AppStorage.appFile(id, ref))).valueOrNull ?? false;
  if (!onDisk) {
    throw StateError(
      'install of $id rejected: manifest i18n ref "$ref" is missing '
      'from the widget package',
    );
  }
}

