  /// (`..`) or a backslash path.
  static String? normalizeRefPath(String raw) {
    var path = raw.trim();
    while (path.startsWith('./')) {
      path = path.substring(2);
    }
    if (path.isEmpty || path.startsWith('/') || path.contains('\\')) {
      return null;
    }
    if (path.split('/').contains('..')) return null;
    return path;
  }
}

