/// Manifest variant opting the app into a live launcher tile.
String _manifestWithTile(String id, String name, String icon, String size) =>
    '''
{
  "id": "$id",
  "name": "$name",
  "description": "$name app",
  "icon": "$icon",
  "widget": { "entry": "widget_tile.js", "size": "$size" }
}
