}) async {
  final env = MemoryExecutionEnv();
  for (final (id, name, icon) in [
    ('alpha', 'Alpha', '🅰️'),
    ('beta', 'Beta', '🅱️'),
    ('gamma', 'Gamma', '🎲'),
  ]) {
